import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.customerGroups().listCustomerGroups(
        Map.of("search_text", "wholesale", "status", "active", "limit", 50));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("customer_groups")) {
    Map<?, ?> group = (Map<?, ?>) row;
    System.out.println(group.get("id") + " " + group.get("name") + " " + group.get("status"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("has_next"));

